import pandas as pd
import re
import random

def task_func(s: str, seed: int = 0) -> pd.DataFrame:
    columns = ["ID", "Quantity", "Code", "Price", "Product", "Description"]
    if not s:
        return pd.DataFrame(columns=columns)

    rng = random.Random(seed)
    product_pool = ["Apple", "Banana", "Orange", "Pear", "Grape"]
    code_to_product = {}
    rows = []

    for line in s.splitlines():
        line = line.strip()
        if not line:
            continue

        parts = re.split(r"\s+", line, maxsplit=4)
        if len(parts) < 4:
            continue
        if len(parts) == 4:
            parts.append("")

        id_str, qty_str, code, price_str, desc = (p.rstrip() for p in parts[:5])

        if code not in code_to_product:
            code_to_product[code] = rng.choice(product_pool)

        try:
            row = {
                "ID": int(id_str),
                "Quantity": int(qty_str),
                "Code": code,
                "Price": int(price_str),
                "Product": code_to_product[code],
                "Description": desc.rstrip(),
            }
        except ValueError:
            continue

        rows.append(row)

    return pd.DataFrame(rows, columns=columns)
